create or replace function "permdock".permdock_has(p_grant text)
returns boolean
language sql
stable
security definer
cost 1000
parallel safe
set search_path = ''
as $$
  select coalesce((select "permdock".permdock_user_id())::text, '') <> '' and exists (
    select 1
    from jsonb_array_elements_text(
      case jsonb_typeof(coalesce(nullif(((select auth.jwt()) -> 'user_role'), 'null'::jsonb), (select auth.jwt()) -> 'app_metadata' -> 'user_role'))
        when 'array' then coalesce(nullif(((select auth.jwt()) -> 'user_role'), 'null'::jsonb), (select auth.jwt()) -> 'app_metadata' -> 'user_role')
        when 'string' then jsonb_build_array(coalesce(nullif(((select auth.jwt()) -> 'user_role'), 'null'::jsonb), (select auth.jwt()) -> 'app_metadata' -> 'user_role'))
        else '[]'::jsonb
      end
    ) r(role)
    join "permdock".role_permissions rp on rp.role = r.role
    where rp.grant_key = p_grant
      and rp.scope = 'global'
  )
$$;
revoke execute on function "permdock".permdock_has(text) from public, anon;
grant execute on function "permdock".permdock_has(text) to authenticated;

create or replace function "permdock".permitted_tenant_ids(p_grant text)
returns setof uuid
language sql
stable
security definer
cost 1000
parallel safe
set search_path = ''
as $$
  select (m ->> 'id')::uuid
  from jsonb_array_elements(
      case jsonb_typeof(coalesce(((select auth.jwt()) -> 'memberships'), (select auth.jwt()) -> 'app_metadata' -> 'memberships')) when 'array' then coalesce(((select auth.jwt()) -> 'memberships'), (select auth.jwt()) -> 'app_metadata' -> 'memberships') else '[]'::jsonb end
    ) m
    cross join lateral jsonb_array_elements_text(
      case jsonb_typeof(m -> 'roles') when 'array' then m -> 'roles' else '[]'::jsonb end
    ) r(role)
  join "permdock".role_permissions rp on rp.role = r.role
  where coalesce((select "permdock".permdock_user_id())::text, '') <> ''
    and rp.grant_key = p_grant
    and rp.scope = 'tenant'
    and m ->> 'scope' = 'tenant'
    and m ->> 'id' is not null
    and (nullif(((select auth.jwt()) ->> 'tenant_id'), '') is null or m ->> 'id' = nullif(((select auth.jwt()) ->> 'tenant_id'), ''))
    and case jsonb_typeof(m -> 'expires_at')
      when 'number' then (m ->> 'expires_at')::numeric > extract(epoch from now())
      else true
    end
$$;
revoke execute on function "permdock".permitted_tenant_ids(text) from public, anon;
grant execute on function "permdock".permitted_tenant_ids(text) to authenticated;

create or replace function "permdock".member_tenant_ids()
returns setof uuid
language sql
stable
security definer
cost 1000
set search_path = ''
as $$
  select distinct (m ->> 'id')::uuid
  from jsonb_array_elements(
    case jsonb_typeof(coalesce(((select auth.jwt()) -> 'memberships'), (select auth.jwt()) -> 'app_metadata' -> 'memberships')) when 'array' then coalesce(((select auth.jwt()) -> 'memberships'), (select auth.jwt()) -> 'app_metadata' -> 'memberships') else '[]'::jsonb end
  ) m
  where coalesce((select "permdock".permdock_user_id())::text, '') <> ''
    and m ->> 'scope' = 'tenant'
    and m ->> 'id' is not null
    and jsonb_typeof(m -> 'roles') = 'array'
    and jsonb_array_length(m -> 'roles') > 0
    and case jsonb_typeof(m -> 'expires_at')
      when 'number' then (m ->> 'expires_at')::numeric > extract(epoch from now())
      else true
    end
$$;
revoke execute on function "permdock".member_tenant_ids() from public, anon;
grant execute on function "permdock".member_tenant_ids() to authenticated;

